import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class ConnectionPool {

    private static ConnectionPool instance;
    private BlockingQueue<Connection> availableConnections;
    private BlockingQueue<Connection> usedConnections;
    private String url;
    private String username;
    private String password;
    private String driverClass;
    private int maxPoolSize;
    private int initialPoolSize;
    private AtomicInteger totalCreated;
    private long connectionTimeout;
    private long validationTimeout;
    private boolean autoCommit;
    private int transactionIsolation;

    private ConnectionPool() {
        totalCreated = new AtomicInteger(0);
        connectionTimeout = 30000;
        validationTimeout = 5000;
        autoCommit = true;
        transactionIsolation = Connection.TRANSACTION_READ_COMMITTED;
    }

    public static synchronized ConnectionPool getInstance() {
        if (instance == null) {
            instance = new ConnectionPool();
        }
        return instance;
    }

    public void initialize(String url, String username, String password, int initialSize, int maxSize) throws SQLException {
        initialize(url, username, password, initialSize, maxSize, null);
    }

    public void initialize(String url, String username, String password, int initialSize, int maxSize, String driverClass) throws SQLException {
        this.url = url;
        this.username = username;
        this.password = password;
        this.initialPoolSize = initialSize;
        this.maxPoolSize = maxSize;
        this.driverClass = resolveDriverClass(driverClass, url);
        this.availableConnections = new ArrayBlockingQueue<>(maxSize);
        this.usedConnections = new ArrayBlockingQueue<>(maxSize);

        try {
            Class.forName(this.driverClass);
        } catch (ClassNotFoundException e) {
            throw new SQLException("JDBC driver not found: " + this.driverClass, e);
        }

        for (int i = 0; i < initialSize; i++) {
            availableConnections.add(createConnection());
        }
    }

    private String resolveDriverClass(String driverClass, String url) {
        if (driverClass != null && !driverClass.trim().isEmpty()) {
            return driverClass.trim();
        }
        if (url != null && url.startsWith("jdbc:postgresql")) {
            return "org.postgresql.Driver";
        }
        return "com.microsoft.sqlserver.jdbc.SQLServerDriver";
    }

    private Connection createConnection() throws SQLException {
        Connection conn = DriverManager.getConnection(url, username, password);
        conn.setAutoCommit(autoCommit);
        conn.setTransactionIsolation(transactionIsolation);
        totalCreated.incrementAndGet();
        return conn;
    }

    public Connection getConnection() throws SQLException {
        Connection connection = null;
        try {
            connection = availableConnections.poll(connectionTimeout, TimeUnit.MILLISECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new SQLException("Interrupted while waiting for connection", e);
        }

        if (connection == null) {
            if (totalCreated.get() < maxPoolSize) {
                connection = createConnection();
            } else {
                throw new SQLException("Connection pool exhausted. Max pool size: " + maxPoolSize);
            }
        }

        if (!isConnectionValid(connection)) {
            connection = createConnection();
        }

        usedConnections.add(connection);
        return connection;
    }

    public void releaseConnection(Connection connection) {
        if (connection != null) {
            usedConnections.remove(connection);
            try {
                if (!connection.isClosed()) {
                    if (!connection.getAutoCommit()) {
                        connection.rollback();
                        connection.setAutoCommit(autoCommit);
                    }
                    availableConnections.offer(connection);
                } else {
                    totalCreated.decrementAndGet();
                }
            } catch (SQLException e) {
                totalCreated.decrementAndGet();
            }
        }
    }

    private boolean isConnectionValid(Connection connection) {
        try {
            if (connection == null || connection.isClosed()) {
                return false;
            }
            return connection.isValid((int) (validationTimeout / 1000));
        } catch (SQLException e) {
            return false;
        }
    }

    public void shutdown() {
        for (Connection conn : usedConnections) {
            try {
                conn.close();
            } catch (SQLException ignored) {}
        }
        for (Connection conn : availableConnections) {
            try {
                conn.close();
            } catch (SQLException ignored) {}
        }
        availableConnections.clear();
        usedConnections.clear();
        totalCreated.set(0);
    }

    public int getAvailableCount() {
        return availableConnections.size();
    }

    public int getUsedCount() {
        return usedConnections.size();
    }

    public int getTotalCreated() {
        return totalCreated.get();
    }

    public void setConnectionTimeout(long timeout) {
        this.connectionTimeout = timeout;
    }

    public void setValidationTimeout(long timeout) {
        this.validationTimeout = timeout;
    }

    public void setAutoCommit(boolean autoCommit) {
        this.autoCommit = autoCommit;
    }

-- PostgreSQL-compatible migration notes for AlloyDB
-- This file is a starting point for translating the SQL Server DDL.

-- Example type mappings:
-- SQL Server: DATETIME -> PostgreSQL: TIMESTAMP
-- SQL Server: BIT -> PostgreSQL: BOOLEAN
-- SQL Server: IDENTITY -> PostgreSQL: GENERATED ALWAYS AS IDENTITY

-- Recommended initial steps:
-- 1. Create the database and schema.
-- 2. Recreate tables with PostgreSQL-compatible syntax.
-- 3. Recreate indexes and foreign keys.
-- 4. Load seed data.

CREATE SCHEMA IF NOT EXISTS retail;

-- Example table skeleton:
-- CREATE TABLE retail.tbl_region (
--   region_id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
--   region_name VARCHAR(100) NOT NULL,
--   region_code VARCHAR(10) NOT NULL UNIQUE,
--   country_code VARCHAR(5) NOT NULL DEFAULT 'US',
--   tax_rate NUMERIC(5,4) NOT NULL DEFAULT 0.0000,
--   is_active BOOLEAN NOT NULL DEFAULT TRUE,
--   created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
--   modified_date TIMESTAMP NULL
-- );
Run the script using SQL Server Management Studio, Azure Data Studio, or `sqlcmd`. For example:

```bash
sqlcmd -S localhost,1433 -U sa -P '<sql-server-password>' -i sql/schema.sql
```

> **Warning:** `sql/schema.sql` drops `RetailCoreDB` if it already exists. Do not run it against a database containing data you need to preserve.

The script contains `GO` batch separators, so use a SQL Server-aware client such as SSMS, Azure Data Studio, or `sqlcmd`.

## Configuration

Database settings are read from [`src/main/resources/database.properties`](src/main/resources/database.properties). The important properties are:

```properties
db.url=jdbc:sqlserver://localhost:1433;databaseName=RetailCoreDB;encrypt=false;trustServerCertificate=true
db.username=sa
db.password=<sql-server-password>
db.pool.initial=5
db.pool.max=20
db.connection.timeout=30000
db.validation.timeout=5000
```

Update the URL, username, and password for the local SQL Server instance before running the application. Do not commit real production credentials to source control.

`DatabaseConfig` first loads the classpath resource above and then falls back to `config/database.properties` if the resource is unavailable.

## Build

From the repository root:

```bash
mvn clean package
```

The packaged JAR is created under `target/`.

## Run

After configuring SQL Server and the database properties, run the packaged application with:

```bash
java -jar target/retail-legacy-1.0.0.jar
```

